.gallery-wrapper {
    max-width: 1219px;
    margin: 0 auto 96px auto;
    padding: 40px 40px;
    box-sizing: border-box;
    background: white;
    border-radius: 20px;
}

.gallery-header {
    font-family: 'Inter', sans-serif;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    margin-bottom: 32px;
    font-weight: 600;
    size: 62px;
}

.gallery-title {
    font-size: 36px;
    color: #000637;
    font-weight: 600;
    margin: 0;
}

.gallery-controls {
    display: flex;
    align-items: center;
    gap: 100px;
}

.gallery-toggle {
    padding: 0 5px;
    background: rgba(211, 211, 211, 0.27);
    display: flex;
    overflow: hidden;
    max-width: 330px;
    height: 48px;
    border-radius: 10px;
    justify-content: space-around;
    align-items: center;
}

.toggle-btn {
    color: #000637;
    height: 38px;
    width: 154px;
    border: none;
    background: transparent;
    padding: 8px 16px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    justify-content: center;

}
.toggle-btn svg {
    display: block;            /* prevents baseline misalignment */
}


.toggle-btn.active {
    background-color: rgba(153, 50, 204, 0.3);
    border-radius: 10px;
}

.gallery-arrows {
    display: flex;
    gap: 5px;
}

.arrow {
    background: rgba(211, 211, 211, 0.27);
    border: none;
    border-radius: 10px;
    width: 48px;
    height: 48px;
    cursor: pointer;
    transition: background 0.3s;
}

.arrow:hover {
    background: #ddd;
}

.gallery-slider {
    overflow: hidden;
    width: 100%;
    position: relative;
}

.gallery-track {
    display: flex;
    transition: transform 0.5s ease;
    gap: 20px;
}

.gallery-item {
    border-radius: 12px;
    width: 269px;
    height: 320px;
    flex-shrink: 0;
    background-image: url("/images/mybus/img.png");
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center;
}

.gallery-item a {
    position: absolute;
    width: 269px;
    height: 320px;
}

.gallery-item.barcelona {
    background-image: url("/images/mybus/barcelona.webp");
}

.gallery-item.prague {
    background-image: url("/images/mybus/card_prague.jpg");
}
.gallery-item.vienna {
    background-image: url("/images/mybus/vienna.webp");
}
.gallery-item.budapesht {
    background-image: url("/images/mybus/budapesht.webp");
}


.gallery-item.gdansk {
    background-image: url("/images/mybus/IMG_5113.webp");
}

.gallery-item.kyiv {
    background-image: url("/images/mybus/IMG_5114.webp");
}
.gallery-item.krakiv {
    background-image: url("/images/mybus/IMG_5115.webp");
}
.gallery-item.dortmund {
    background-image: url("/images/mybus/IMG_5116.webp");
}



