.floating-support-btn-container {
    bottom: 15px;
    right: 15px;
    position: fixed;
    z-index: 999990;
    --floating-btn-size: 56px;
}

.floating-support-btn-toggle {
    height: var(--floating-btn-size);
    width: var(--floating-btn-size);
    bottom: 0;
    right: 0;
    position: absolute;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    background-color: #fcfcfc;
    box-shadow: 3px 3px 2px 1px #00000033;
    z-index: 2;
    cursor: pointer;
}

.floating-support-btn-list .floating-support-btn-menu-item {
    height: var(--floating-btn-size);
    width: var(--floating-btn-size);
    bottom: 0;
    right: 0;
    position: absolute;
    border-radius: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: 0.3s;
}

.floating-support-btn-icon {
    height: var(--floating-btn-size);
    width: var(--floating-btn-size);
}

.floating-support-btn-icon-wrapper {
    height: var(--floating-btn-size);
    width: var(--floating-btn-size);
    border-radius: 50%;
    overflow: hidden;
}

.floating-support-btn-toggle.effect {
    border: 1px solid #00000033;
}

.floating-support-btn-toggle i {
    font-size: 2rem;
    color: #eeeeee;
    transition: 0.3s;
}

.floating-support-btn-close {
    display: none;
}

.floating-support-btn-toggle.effect .floating-support-btn-close {
    display: block;
}

.floating-support-btn-toggle.effect .floating-support-btn-icon {
    display: none;
}

.floating-support-btn-toggle.effect i {
    transform: rotate(135deg);
}

.floating-support-btn-list {
    list-style: none;
    bottom: 0;
    right: 0;
    position: absolute;
    z-index: 1;
}

.floating-support-btn-list .floating-support-btn-menu-item a {
    text-decoration: none;
    color: #eeeeee;
}

.floating-support-btn-list .floating-support-btn-menu-item:hover {
}

.floating-support-btn-list.effect .floating-support-btn-menu-item {
    box-shadow: 3px 3px 2px 1px rgba(0, 0, 0, 0.2);
}

.floating-support-btn-list.effect .floating-support-btn-menu-item:nth-of-type(1) {
    bottom: 210px;
    right: 0;
}

.floating-support-btn-list.effect .floating-support-btn-menu-item:nth-of-type(2) {
    bottom: 140px;
    right: 0;
}

.floating-support-btn-list.effect .floating-support-btn-menu-item:nth-of-type(3) {
    bottom: 70px;
    right: 0;
}
